import React, { useState } from "react";
import Button from "@mui/material/Button";
import Menu from "@mui/material/Menu";
import MenuItem from "@mui/material/MenuItem";
import CupcakeGallery from "../ProductGalleries/CupcakeGallery";
import cupcakesList from "../CupcakesList";


const [selectedMenu, setSelectedMenu] = useState(null);


function DropdownMenu() {
  const [anchorEl, setAnchorEl] = useState(null);

  const handleClick = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  return (
    <div className="dropdownButton">
      <Button
        aria-controls="simple-menu"
        aria-haspopup="true"
        onClick={handleClick}
        variant="contained"
        
      >
        The sorting coffee machine
      </Button>
      <Menu
        id="simple-menu"
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleClose}
        PaperProps={{ style: {width: "50%"},}}
      >
        <MenuItem onClick={handleClose} sx={{ justifyContent: "center", fontWeight: "bold", fontSize: "1.2rem", borderBottom: "1px solid #592C22"}}>Muffins</MenuItem>
        <MenuItem onClick={handleClose} sx={{ justifyContent: "center", fontWeight: "bold", fontSize: "1.2rem",borderBottom: "1px solid #592C22"}}>Cupcakes</MenuItem>
        <MenuItem onClick={handleClose} sx={{ justifyContent: "center", fontWeight: "bold", fontSize: "1.2rem",}}>Vegan</MenuItem>
      </Menu>
    </div>
  );
}

export default DropdownMenu;
